from runtime_sdk import NodeContext


def run(ctx: NodeContext):
    """摘要：按目标长度压缩内容。"""
    limit = ctx.params.get("max_chars", 300)
    return ctx.llm(f"用不超过 {limit} 字概括要点：\n{ctx.text}", system="只输出摘要正文。")

