def run(ctx):
    """会话落盘：中断后能按同一份状态接着跑。"""
    transcript = ctx.state.get('transcript') or []
    ctx.write_file('session.jsonl',
                   '\n'.join(str(x)[:2000] for x in transcript))
    return {'data': ctx.text}

